{"proposals": [
{"verb": "disclose_account", "target": "Maryam (synthetic) invoice October 2026", "args": {"invoice_total_aed": 230, "usual_invoice_aed": 185, "breakdown": [{"item": "monthly plan", "aed": 185}, {"item": "premium content subscription, charged 2026-10-03", "aed": 45}], "difference_aed": 45, "verification_level": "medium (app login, device binding)"}, "clause_ids": ["tdra-cpr-v2-en:24.10"], "quote": "the Licensee shall disclose it free of charge and without delay after an adequate verification process.", "rationale": "The subscriber asks about her own bill. The AED 45 difference comes from a premium content subscription charged on 2026-10-03. Disclosure is free, and the gate decides whether medium verification is adequate."},
{"verb": "propose_change", "target": "Premium content subscription charged 2026-10-03 (AED 45)", "args": {"action": "cancel subscription and refund/credit AED 45", "reason": "no consent record on file", "complaint_reference": "SAH-C-2026-NNNN (synthetic) to be opened", "handoff": "Human agent H-01 (synthetic) to confirm"}, "clause_ids": ["tdra-cpr-v2-en:4.3", "tdra-cpr-v2-en:4.7.1"], "quote": "shall not register, charge or otherwise avail a Service to a Subscriber that the Subscriber has not expressly ordered", "rationale": "Sahab has no consent record for the premium content subscription, so the AED 45 charge appears to be one the subscriber never expressly ordered. I propose cancelling it and crediting the amount, subject to the gates and human review."}
],
"notes": ["Tell the subscriber plainly that the extra AED 45 is a premium content subscription with no consent on file, and that we are proposing to cancel it and refund the amount.", "The subscriber's preferred language is Arabic, but this run is English. Offer an Arabic follow-up.", "Do not propose any new sale in this reply."]}
